import pdfplumber
import io
import re
import base64
import hashlib

# 1. Recuperiamo l'elemento in ingresso e la stringa Base64 creata dal nodo JavaScript
item = _items[0]
binary_data = item["json"]["pdf_base64"]

# Riconvertiamo la stringa nei byte reali del PDF
pdf_bytes = io.BytesIO(base64.b64decode(binary_data))

# Calcolo Hash MD5 del file originale per identificazione univoca
file_hash = hashlib.md5(pdf_bytes.getvalue()).hexdigest()

testo_pulito = ""
pdf_metadata = {}

# 2. Analisi visuale del PDF con pdfplumber
with pdfplumber.open(pdf_bytes) as pdf:
    # Salviamo i metadati nativi del file PDF (es. CreationDate)
    if pdf.metadata:
        for k, v in pdf.metadata.items():
            try:
                if isinstance(v, bytes):
                    pdf_metadata[k] = v.decode('utf-8', errors='ignore')
                else:
                    pdf_metadata[k] = str(v)
            except:
                pass

    # Aggiungiamo 'enumerate' per tracciare il numero di pagina
    for i, page in enumerate(pdf.pages):
        width = page.width
        height = page.height

        # 3. RIMOZIONE GEOMETRICA DEL RUMORE
        # Sulla prima pagina (i=0) il margine superiore è piccolissimo (5%) per salvare il titolo.
        # Sulle pagine successive applichiamo il taglio standard del 15% per rimuovere intestazioni.
        if i == 0:
            top_margin = height * 0.05
        else:
            top_margin = height * 0.15

        bottom_margin = height * 0.90  # Ignora l'ultimo 10% in basso

        # Definiamo l'area utile (x0, top, x1, bottom)
        bbox = (0, top_margin, width, bottom_margin)
        cropped_page = page.crop(bbox)

        # Estraiamo il testo SOLO dalla parte centrale della pagina
        page_text = cropped_page.extract_text()

        if page_text:
            testo_pulito += page_text + "\n\n"

# FIX BUG PDFPLUMBER: Decodifica manuale dei caratteri (cid:XX) generati dai font Ghostscript
def decodifica_cid(match):
    try:
        return chr(int(match.group(1)))
    except:
        return match.group(0)

testo_pulito = re.sub(r'\(cid:(\d+)\)', decodifica_cid, testo_pulito)

# 4. TAGLIO DELLA CODA DEL DOCUMENTO
art_fine_match = re.search(r'\nART[\.\s]+[56789]\s*[–\-]', testo_pulito, re.IGNORECASE)

if not art_fine_match:
    art_fine_match = re.search(
        r'\n\s*(Modalità di presentazione|Domanda di partecipazione|Presentazione della domanda|Valutazione dei candidati|Commissione giudicatrice)', 
        testo_pulito, 
        re.IGNORECASE
    )

if art_fine_match:
    testo_ridotto = testo_pulito[:art_fine_match.start()]
else:
    testo_ridotto = testo_pulito[:6000]

testo_ridotto = re.sub(r'\n{3,}', '\n\n', testo_ridotto).strip()

# Restituiamo il risultato al formato JSON compatibile con i nodi successivi
return [{"json": {
    "testo_ridotto": testo_ridotto,
    "file_hash": file_hash,
    "metadati_pdf": pdf_metadata
}}]

